import { BaseSubscreen } from "../ui";
import { CoreButtonShard } from "./shards/coreButtonShard";
import { StyleModule } from "../shard-modules";
import { CoreCheckboxShard, CoreInputListShard, CoreSelectShard, CoreTextShard } from "./shards";
class CoreSubscreen extends BaseSubscreen {
  g = 40;
  h = 0.05;
  interval = null;
  run() {
    DrawRect(0, 0, 2e3, 1e3, "#008600ff");
    for (let x = 0; x <= 2e3; x += this.g) {
      DrawRect(x, 0, 5, 1e3, "#17a117ff");
    }
    for (let y = 0; y <= 1e3; y += this.g) {
      DrawRect(0, y, 2e3, 5, "#17a117ff");
    }
  }
  load() {
    this.createText({
      x: 60,
      y: 40,
      text: this.name,
      fontSize: 6,
      modules: {
        base: [
          new StyleModule({
            fontWeight: "bold"
          })
        ]
      }
    });
    this.createButton({
      anchor: "top-right",
      x: 40,
      y: 40,
      width: 90,
      height: 90,
      icon: "Icons/Exit.png",
      onClick: () => this.exit()
    });
    this.g = 40;
    this.h = 0.05;
    this.interval = setInterval(() => {
      this.g += this.h;
      if (this.g >= 60) this.h = -0.05;
      if (this.g <= 40) this.h = 0.05;
    }, 50);
  }
  createText(ctx) {
    const shard = new CoreTextShard(ctx);
    const htmlElement = shard.mount();
    return htmlElement;
  }
  createButton(ctx) {
    const shard = new CoreButtonShard(ctx);
    const htmlElement = shard.mount();
    return htmlElement;
  }
  createCheckbox(ctx) {
    const shard = new CoreCheckboxShard(ctx);
    const htmlElement = shard.mount();
    return htmlElement;
  }
  createInputList(ctx) {
    const shard = new CoreInputListShard(ctx);
    const htmlElement = shard.mount();
    return htmlElement;
  }
  createSelect(ctx) {
    const shard = new CoreSelectShard(ctx);
    const htmlElement = shard.mount();
    return htmlElement;
  }
  unload() {
    super.unload();
    if (this.interval) clearInterval(this.interval);
  }
}
export {
  CoreSubscreen
};
